<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Delete;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\DcrInitialAccessTokenRef;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Service\Visibility\DcrInitialAccessTokenVisibilityService;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Gateway\DcrInitialAccessTokenCommandRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class DcrInitialAccessTokenDeleteUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly DcrInitialAccessTokenVisibilityService $visibility,
        private readonly DcrInitialAccessTokenCommandRepositoryGateway $writer,
    ) {
    }

    public function allowDelete(?DcrInitialAccessTokenRef $ref = null): Allow
    {
        $this->logDebug("Check allow of delete usecase for Dcr initial access token");
        $span = $this->startSpan("Check allow of delete usecase for Dcr initial access token");
        try {
            $result = $this->dispatcher->dispatch(new DcrInitialAccessTokenDeleteAllowDecision(Allow::allowed('delete', 'Allowed to delete by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function delete(string $uid): void
    {
        $this->logDebug("Run delete usecase for Dcr initial access token");
        $span = $this->startSpan("Run delete usecase for Dcr initial access token");
        try {
            $ref = new DcrInitialAccessTokenRef($uid);
            $allow = $this->allowDelete($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to delete Dcr initial access token');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new DcrInitialAccessTokenDeleteCheck($original));
            $deleted = $original->delete();
            $this->writer->delete($deleted);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
